package app.befare.core

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlin.math.ceil

// ---- Fare bundle (data/fares/fares.json, generated by scripts/build_fares.py) -------------------

@Serializable
data class FareBundle(val version: String, val currency: String, val sources: List<FareSource>, val modes: List<FareMode>)

@Serializable
data class FareSource(
    val id: String,
    val issuer: String,
    val document: String,
    val effectiveDate: String? = null,
    val assets: List<SourceAsset> = emptyList(),
    val verified: Boolean = false,
    val notes: String? = null,
)

@Serializable
data class SourceAsset(val file: String, val sha256: String? = null)

@Serializable
data class FareMode(val mode: String, val rules: List<FareRule>, val discounts: List<Discount> = emptyList())

@Serializable
data class FareRule(
    val id: String,
    val type: String,
    val label: String,
    val sourceId: String,
    val kmRounding: String,
    val kmRoundingVerified: Boolean = false,
    val maxKm: Int,
    val currentBand: CurrentBand? = null,
    val bands: List<FuelBand>,
)

@Serializable
data class CurrentBand(val id: String? = null, val asOf: String? = null, val basis: String? = null)

@Serializable
data class FuelBand(
    val id: String,
    val label: String,
    val gasMinCentavos: Long? = null,
    val gasMaxCentavos: Long? = null,
    val minimumFare: Long,
    val fares: List<Long>,
)

@Serializable
data class Discount(val id: String, val label: String, val type: String, val value: Int, val sourceId: String)

// ---- Quote --------------------------------------------------------------------------------------

data class BreakdownLine(val label: String, val detail: String, val amountCentavos: Long?)

data class BandFare(val bandId: String, val label: String, val centavos: Long)

data class FareQuote(
    val distanceM: Double,
    val chargedKm: Int,
    val band: FuelBand,
    val fareCentavos: Long,
    val discountLabel: String?,
    val discountedCentavos: Long?,
    val lines: List<BreakdownLine>,
    /** The matrix row for [chargedKm] across every band, for the Verify screen. */
    val row: List<BandFare>,
    val source: FareSource,
    val dataVersion: String,
    val assumptions: List<String>,
)

sealed interface FareResult {
    data class Ok(val quote: FareQuote) : FareResult
    data class OverTable(val chargedKm: Int, val maxKm: Int) : FareResult
}

/** Tricycle fares from a `distance_table_by_fuel_band` rule (City Ordinance No. 1185). */
class FareCalculator(val bundle: FareBundle) {

    private val mode = bundle.modes.first { it.mode == "tricycle" }
    private val rule = mode.rules.first { it.type == "distance_table_by_fuel_band" }
    private val source = bundle.sources.first { it.id == rule.sourceId }
    private val discount = mode.discounts.firstOrNull()

    val bands: List<FuelBand> get() = rule.bands
    val defaultBandId: String get() = rule.currentBand?.id ?: rule.bands.first().id
    val isCurrentBandSet: Boolean get() = rule.currentBand?.id != null

    fun quote(distanceM: Double, bandId: String): FareResult {
        val band = rule.bands.first { it.id == bandId }
        val metres = kotlin.math.round(distanceM)
        val km = maxOf(1, ceil(metres / 1000.0).toInt())
        if (km > rule.maxKm) return FareResult.OverTable(km, rule.maxKm)

        val fare = band.fares[km - 1]
        val doc = "Ord. ${documentNumber()}"
        val lines = buildList {
            add(BreakdownLine("Route distance", "${fmtKm(metres)} km by road (BeFare routing)", null))
            add(BreakdownLine("Charged as", "$km km — a started kilometre counts as a full km", null))
            add(BreakdownLine("Fare, $km km · ${band.label}", "$doc matrix, row $km", fare))
        }
        val discounted = discount?.let { fare * (100 - it.value) / 100 }
        val allLines = if (discount != null && discounted != null) {
            lines + BreakdownLine("${discount.label} −${discount.value}%", "$doc (mandatory 20% discount)", discounted - fare) +
                BreakdownLine("Discounted fare", "No rounding rule stated", discounted)
        } else lines

        val assumptions = buildList {
            add("Distance is the shortest road route. The driver's actual route may differ.")
            if (!rule.kmRoundingVerified) add("Partial kilometres are rounded up. This isn't stated on the matrix and still needs checking against the ordinance text.")
            if (!isCurrentBandSet) add("The current gas price hasn't been set in this data version. Pick the band that matches today's pump price.")
            if (!source.verified) add("The transcription hasn't been checked by a second person yet.")
            if (source.effectiveDate == null) add("The ordinance's effective date isn't confirmed.")
        }

        return FareResult.Ok(
            FareQuote(
                distanceM = distanceM,
                chargedKm = km,
                band = band,
                fareCentavos = fare,
                discountLabel = discount?.label,
                discountedCentavos = discounted,
                lines = allLines,
                row = rule.bands.map { BandFare(it.id, it.label, it.fares[km - 1]) },
                source = source,
                dataVersion = bundle.version,
                assumptions = assumptions,
            )
        )
    }

    private fun documentNumber() = Regex("No\\. (\\d+)").find(source.document)?.groupValues?.get(1) ?: source.id

    private fun fmtKm(metres: Double): String {
        val tenths = kotlin.math.round(metres / 100).toLong()
        return "${tenths / 10}.${tenths % 10}"
    }

    companion object {
        private val json = Json { ignoreUnknownKeys = true }
        fun fromJson(text: String) = FareCalculator(json.decodeFromString(FareBundle.serializer(), text))
    }
}

/** Formats centavos as pesos, e.g. 1760 -> "₱17.60". */
fun formatPeso(centavos: Long): String {
    val sign = if (centavos < 0) "−" else ""
    val abs = kotlin.math.abs(centavos)
    return "$sign₱${abs / 100}.${(abs % 100).toString().padStart(2, '0')}"
}
